    // Initialize an empty object to store the counts
    const charCount = {};

    // Loop through each character in the string
    for (let char of str) {
        // If the character is already a key in the object, increment its value
        if (charCount[char]) {
            charCount[char]++;
        } else {
            // Otherwise, add the character to the object with a value of 1
            charCount[char] = 1;
        }
