A Binary Search Tree (BST) is a data structure that keeps data sorted and allows for efficient insertion, deletion, and lookup operations. Below is a simple implementation of a BST in Python, including methods for inserting a new node, searching for a value, and traversing the tree.

### Binary Search Tree Implementation

```python
class TreeNode:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

def insert(root, key):
    # If the tree is empty, return a new node
    if root is None:
        return TreeNode(key)

    # Otherwise, recur down the tree
    if key < root.val:
        root.left = insert(root.left, key)
    else:
        root.right = insert(root.right, key)

    # Return the (unchanged) node pointer
    return root

def inorder_traversal(root):
    # Traverse the left subtree
    if root:
        inorder_traversal(root.left)

        # Visit the node
        print(root.val, end=' ')

        # Traverse the right subtree
        inorder_traversal(root.right)

def search(root, key):
    # Base Cases: root is null or key is present at root
    if root is None or root.val == key:
        return root

    # Key is greater than root's key
    if root.val < key:
        return search(root.right, key)

    # Key is smaller than root's key
    return search(root.left, key)

# Example usage:
if __name__ == "__main__":
    r = None
    keys = [50, 30, 70, 20, 40, 60, 80]

    # Insert nodes into the BST
    for key in keys:
        r = insert(r, key)

    # Print the tree in order
    print("Inorder traversal of the BST:")
    inorder_traversal(r)

    # Search for a key
    found_node = search(r, 60)
    if found_node:
        print("\nFound:", found_node.val)
    else:
        print("\nNot Found")
```

